#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

/* Return the index of the last Book item in the vector books where Book.pages is less than 100.
   If no such book exists, returns books.size().
*/
size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    long long best = -1;  // signed sentinel for "not found"

    #pragma omp parallel for reduction(max:best)
    for (long long i = 0; i < static_cast<long long>(n); ++i) {
        if (books[static_cast<size_t>(i)].pages < 100) {
            if (i > best) best = i;
        }
    }

    return (best >= 0) ? static_cast<size_t>(best) : n;
}
